classdef TestLegacyReproducibility < matlab.unittest.TestCase
    %TESTLEGACYREPRODUCIBILITY  The frozen legacy code reproduces its fixtures.
    %
    %   The golden-master fixtures in tests/fixtures were generated by
    %   running legacy/main1.m. This test runs the legacy code again and
    %   checks that the final state and every output file are identical, so
    %   it guards two things: the fixtures are valid, and the legacy code
    %   is deterministic and has not been modified by accident.
    %
    %   Each case starts a child MATLAB process (~15 s), hence the "Slow" tag.
    %   Run it with: run_tests(IncludeSlow=true)
    %
    %   See also generateReference, referenceCases.

    properties (TestParameter)
        caseName = {'tension101_elastic', 'tension101_damage', 'bending102'}
    end

    properties
        FixtureDir
    end

    methods (TestClassSetup)
        function addTools(testCase)
            testsDir = fileparts(fileparts(mfilename('fullpath')));
            testCase.applyFixture(matlab.unittest.fixtures.PathFixture( ...
                fullfile(testsDir, 'tools')));
            testCase.FixtureDir = fullfile(testsDir, 'fixtures');
        end
    end

    methods (Test, TestTags = {'Regression', 'Slow'})
        function legacyMatchesFixture(testCase, caseName)
            fixture = load(fullfile(testCase.FixtureDir, caseName + ".mat"));

            workDir = testCase.applyFixture( ...
                matlab.unittest.fixtures.TemporaryFolderFixture).Folder;
            [state, files] = runLegacyCase(fixture.caseDef, workDir);

            % Numerical state: every variable, with a descriptive message.
            fields = fieldnames(fixture.state);
            testCase.verifyEqual(sort(fieldnames(state)), sort(fields), ...
                'The set of saved state variables changed.');
            for k = 1:numel(fields)
                f = fields{k};
                testCase.verifyEqual(state.(f), fixture.state.(f), ...
                    'RelTol', 1e-12, 'AbsTol', 1e-14, ...
                    sprintf('State variable %s differs from the fixture.', f));
            end

            % Text outputs: byte-for-byte.
            testCase.verifyEqual(sort(fieldnames(files)), ...
                sort(fieldnames(fixture.files)), ...
                'The set of output files changed.');
            outputs = fieldnames(fixture.files);
            for k = 1:numel(outputs)
                f = outputs{k};
                testCase.verifyEqual(files.(f), fixture.files.(f), ...
                    sprintf('Output file %s differs from the fixture.', f));
            end
        end
    end
end
